def deficiency_profile(oracles, n):
    total = 2**n
    return [total - len(oracle_coverage(oracles, d, n)) for d in range(n + 1)]

def find_max_deficient(oracles, n):
    best_t, best_d = None, -1
    for t in all_assignments(n):
        d = min(hamming_distance(f, t) for f in oracles)
        if d > best_d: best_t, best_d = t, d
    return best_t, best_d

def check_insufficiency(m, n, d):
    ball = sum(comb(n, i) for i in range(d + 1))
    return m * ball < 2**n
